"""QuantLib-Python 1.44 oracle for sabrVolatility(..., ql.Normal) (sabr.cpp:94-132)."""

import QuantLib as ql

assert ql.__version__ == "1.44", ql.__version__

POINTS = [
    (0.03, 0.04, 1.0, 0.02, 0.5, 0.4, -0.2),
    (0.05, 0.04, 2.5, 0.02, 0.5, 0.4, -0.2),
    (0.01, 0.035, 5.0, 0.01, 0.0, 0.3, 0.3),
    (0.06, 0.035, 0.5, 0.05, 1.0, 0.6, -0.5),
    (0.025, 0.03, 10.0, 0.015, 0.3, 0.25, 0.1),
    (0.04, 0.04, 1.0, 0.02, 0.5, 0.4, -0.2),
    (0.035, 0.035, 3.0, 0.01, 0.0, 0.3, 0.3),
    (0.03, 0.04, 1.0, 0.02, 0.5, 1e-10, -0.2),
    (0.045, 0.04, 2.0, 0.02, 0.7, 1e-9, 0.4),
    (0.05, 0.04, 0.0, 0.02, 0.5, 0.4, -0.2),
]

for k, f, t, a, b, n, r in POINTS:
    v = ql.sabrVolatility(k, f, t, a, b, n, r, ql.Normal)
    print(f"({k!r}, {f!r}, {t!r}, {a!r}, {b!r}, {n!r}, {r!r}, {v!r}),")
